"""Tests for merging SPDX 3 documents generated by different builds.

The documents of two builds are merged and checked with spdx3-validate, which
downloads the SPDX 3 schema and SHACL model: these tests skip when spdx.org is
not reachable.
"""

import json
import urllib.request

import pytest
from conftest import DEPS_DOCUMENT
from spdx3_validate import validate
from zspdx.model import ComponentPurpose, SBOMComponent
from zspdx.sbom import use_namespace_map
from zspdx.serializers.spdx3 import SPDX3Serializer
from zspdx.version import SPDX_VERSION_3_0

SPDX_MODEL_URL = "https://spdx.org/rdf/3.0.1/spdx-model.ttl"

# Two builds, each with its own namespace prefix.
BUILD_NAMESPACES = ["https://example.com/sbom/build-a", "https://example.com/sbom/build-b"]

# IRI prefix of the License List licenses, which documents import.
LISTED_LICENSE_PREFIX = SPDX3Serializer._LISTED_LICENSE_PREFIX

# The components use the project license, plus a custom one.
LICENSE = "Apache-2.0"
CUSTOM_LICENSE = "LicenseRef-custom"


@pytest.fixture(scope="module")
def spdx_org():
    """Skip when spdx3-validate cannot download the SPDX model."""
    try:
        request = urllib.request.Request(SPDX_MODEL_URL, method="HEAD")
        with urllib.request.urlopen(request, timeout=10):
            pass
    except OSError as e:
        pytest.skip(f"{SPDX_MODEL_URL} not reachable: {e}")


@pytest.fixture
def build_documents(make_graph, tmp_path):
    """Factory serializing one modules-deps document per build.

    Every build has a component of the same name, with a different version, and
    a License List license; the second also has a compound expression with a
    custom license. Returns the document paths.
    """

    def _documents(**serializer_args):
        paths = []
        for index, namespace in enumerate(BUILD_NAMESPACES):
            component = SBOMComponent(
                name="app-sources",
                purpose=ComponentPurpose.SOURCE,
                version=f"1.{index}",
                declared_license=LICENSE,
                concluded_license=f"{LICENSE} AND {CUSTOM_LICENSE}" if index else LICENSE,
            )
            output_dir = tmp_path / f"build-{index}"
            output_dir.mkdir()
            graph = make_graph(component, namespace=namespace)
            assert SPDX3Serializer(graph, SPDX_VERSION_3_0, **serializer_args).serialize(
                str(output_dir)
            )
            paths.append(str(output_dir / f"{DEPS_DOCUMENT}.jsonld"))
        return paths

    return _documents


@pytest.mark.usefixtures("spdx_org")
def test_full_iris_merge(build_documents):
    result = validate(build_documents(namespace_map=False), version="3.0.1", check_merged=True)
    assert result.valid, str(result)


@pytest.mark.usefixtures("spdx_org")
def test_shortened_ids_do_not_merge(build_documents):
    result = validate(build_documents(), version="3.0.1", check_merged=True)
    # each document is valid on its own, as merged checks only run then...
    assert all(error.source == "(merged)" for error in result.errors), str(result)
    # ...but the shortened IDs are the same in both builds, so the two
    # different packages become one with two versions
    assert any("app-sources" in error.message for error in result.errors), str(result)


def test_full_iris_document(build_documents):
    path = build_documents(namespace_map=False)[0]
    with open(path) as f:
        graph = json.load(f)["@graph"]
    document = next(e for e in graph if e["type"] == "SpdxDocument")
    assert "namespaceMap" not in document
    assert document["spdxId"].startswith(BUILD_NAMESPACES[0])
    # License List licenses, including the data license, are imported, not defined
    defined = {e.get("spdxId", "") for e in graph}
    assert not any(i.startswith(LISTED_LICENSE_PREFIX) for i in defined)
    imported = {m["externalSpdxId"] for m in document["import"]}
    assert document["dataLicense"].startswith(LISTED_LICENSE_PREFIX)
    assert {document["dataLicense"], f"{LISTED_LICENSE_PREFIX}{LICENSE}"} <= imported


@pytest.mark.parametrize(
    ("namespace_map", "cmake_cache", "expected"),
    [
        (True, {"SYSBUILD": "True"}, True),
        (False, {}, False),
        (None, {"SYSBUILD": "True"}, False),
        (None, {"SYSBUILD": "ON"}, False),
        (None, {"SYSBUILD": "1"}, False),
        (None, {"SYSBUILD": "OFF"}, True),
        (None, {}, True),
    ],
)
def test_use_namespace_map(namespace_map, cmake_cache, expected):
    assert use_namespace_map(namespace_map, cmake_cache) is expected
